package com.bank.stats;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class BranchStatsDemo {
    private static final Logger log = Logger.getLogger("BranchStats");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Txn> today = List.of(
            new Txn("TX1", new BigDecimal("5000")),
            new Txn("TX2", new BigDecimal("12000")),
            new Txn("TX3", new BigDecimal("8000"))
        );
        List<Txn> holiday = List.of(); // empty branch day

        BranchStatsService service = new BranchStatsService();

        // Identity form: always a concrete value.
        log.info(() -> "Today total   = Rs. " + service.totalAmount(today));
        log.info(() -> "Holiday total = Rs. " + service.totalAmount(holiday)); // 0, not error

        // Optional form: empty means "no answer".
        log.info(() -> "Today largest   = Rs. " +
            service.largestTxn(today).map(Txn::getAmount).map(Object::toString).orElse("<none>"));
        log.info(() -> "Holiday largest = Rs. " +
            service.largestTxn(holiday).map(Txn::getAmount).map(Object::toString).orElse("<none>"));
    }
}

// ─── Would be in model/Txn.java ───
class Txn {
    private final String id;
    private final BigDecimal amount;
        Txn(String id, BigDecimal amount) { this.id = id;
        this.amount = amount; }
    BigDecimal getAmount() { return amount; }
}

// ─── Would be in service/BranchStatsService.java ───
class BranchStatsService {
    // Two-arg reduce: identity ZERO → concrete total even when empty.
    BigDecimal totalAmount(List<Txn> txns) {
        return txns.stream()
            .map(Txn::getAmount)
            .reduce(BigDecimal.ZERO, BigDecimal::add);
    }

    // One-arg reduce: no identity → Optional, empty when the stream is empty.
    Optional<Txn> largestTxn(List<Txn> txns) {
        return txns.stream()
            .reduce((a, b) -> a.getAmount().compareTo(b.getAmount()) >= 0 ? a : b);
    }
}
